  show_signature_block: true,
  show_validity_footer: true,
  round_prices_to_dollar: false,
};

export function quoteDefaultsPayload(record = {}) {
  return QUOTE_DEFAULT_KEYS.reduce((result, key) => {
    if (record[key] !== undefined && record[key] !== null) result[key] = record[key];
    return result;
  }, {});
}

export function quoteDefaultsForm(record = null) {
  return { ...DEFAULT_QUOTE_SETTINGS, ...quoteDefaultsPayload(record || {}) };
}

export function canonicalQuoteDefaults(rows = []) {
  return (rows || []).slice().sort((a, b) => {
    const aTime = Date.parse(a?.created_date || a?.updated_date || "") || 0;
    const bTime = Date.parse(b?.created_date || b?.updated_date || "") || 0;
    if (aTime !== bTime) return aTime - bTime;
    return String(a?.id || "").localeCompare(String(b?.id || ""));
  })[0] || null;
}

export async function loadQuoteDefaults() {
  const rows = await staffEntities.QuoteDefaults.filter({ config_name: "default" });
  return canonicalQuoteDefaults(rows || []);
}

import { useEffect, useState } from "react";
import { History, Loader2, ShieldAlert } from "lucide-react";
import { base44 } from "@/api/base44Client";

import { ListSkeleton } from "@/components/ui/list-skeleton";

const TYPES = [
  { key: "", label: "All" },
  { key: "revision", label: "Estimate revisions" },
  { key: "activity", label: "Opportunity activity" },
];

// Unified admin audit log (#490): merges EstimateRevision + OpportunityActivity
// records into one reverse-chronological, type-filterable timeline so admins
// can trace cross-record changes in a single view instead of per-record panels.
export default function AuditLog() {
  const [me, setMe] = useState(null);
  const [rows, setRows] = useState(null);
  const [capped, setCapped] = useState(false);
  const [type, setType] = useState("");
  const [error, setError] = useState("");

  useEffect(() => { base44.auth.me().then(setMe).catch(() => setMe(false)); }, []);

  useEffect(() => {
    if (me?.role !== "admin") return;
    let live = true;
    const load = async () => {
      setError("");
      try {
        const [revisions, activities] = await Promise.all([
          type === "activity" ? Promise.resolve([]) : base44.entities.EstimateRevision.filter({}, "-updated_date", 150).catch(() => []),
          type === "revision" ? Promise.resolve([]) : base44.entities.OpportunityActivity.filter({}, "-created_date", 150).catch(() => []),
        ]);
        const rev = (Array.isArray(revisions) ? revisions : []).map((r) => ({
          id: `r-${r.id}`, ts: r?.updated_date || r?.created_date || "", kind: "revision",
          label: `Revision ${r?.revision_number ?? "?"}${r?.status ? ` · ${r.status}` : ""}`,
          body: `${r?.estimate_number || r?.estimate_id || ""}${r?.reason ? ` — ${r.reason}` : ""}${r?.created_by_email ? ` · by ${r.created_by_email}` : ""}`,
        }));
        const act = (Array.isArray(activities) ? activities : []).map((a) => ({
          id: `a-${a.id}`, ts: a?.created_date || "", kind: "activity",
          label: String(a?.event_type || "activity").replaceAll("_", " "),
          body: `${a?.summary || ""}${a?.opportunity_id ? ` · opp ${a.opportunity_id.slice(0, 8)}` : ""}`,
        }));
        const merged = [...rev, ...act].sort((a, b) => String(b.ts).localeCompare(String(a.ts)));
        if (live) {
          setRows(merged.slice(0, 200));
          // Honest bound: each source read stops at 150 rows and the merged
          // timeline at 200 — say so instead of implying the log is complete.
          setCapped(revisions.length >= 150 || activities.length >= 150 || merged.length > 200);
        }
      } catch (e) {
        if (live) { setError(e?.message || "Audit records could not be loaded."); setRows([]); }
      }
    };
    load();
    return () => { live = false; };
  }, [me, type]);

  if (me === null) return <div className="p-8"><Loader2 className="h-5 w-5 animate-spin text-gray-400" /></div>;
  if (me?.role !== "admin") {
    return (
      <div className="flex flex-col items-center justify-center gap-2 p-16 text-center">
        <ShieldAlert className="h-8 w-8 text-amber-500" />
        <p className="text-sm font-medium text-gray-700">Admin only — the audit log is restricted to administrators.</p>
      </div>
    );
  }

  return (
    <div className="clay-scope min-h-full bg-gradient-to-br from-rose-50 to-orange-50">
      <div className="mx-auto max-w-5xl p-4 sm:p-6 space-y-3">
        <div className="flex items-center gap-2 bg-white px-4 py-3">
          <History className="h-4 w-4 text-red-500" />
          <h1 className="text-xs font-bold tracking-wide text-gray-600">AUDIT LOG</h1>
          <span className="ml-auto text-xs text-gray-400">{rows?.length ?? 0} records{capped ? " · showing newest only (capped)" : ""}</span>
        </div>
        <div className="flex gap-1.5">
          {TYPES.map((t) => (
            <button type="button" key={t.key} onClick={() => setType(t.key)}
              className={`px-3 py-1.5 rounded-full text-xs font-semibold border ${type === t.key ? "bg-red-600 text-white border-red-600" : "bg-white/70 text-gray-600 border-gray-200 hover:border-red-300"}`}>
              {t.label}
            </button>
          ))}
        </div>
        {error && <div className="border border-red-200 bg-red-50 px-3 py-2 text-xs text-red-700">{error}</div>}
        <div className="bg-white">
          {rows === null ? <ListSkeleton rows={10} /> : rows.length === 0 ? (
            <div className="px-4 py-10 text-center text-sm text-gray-500">No audit records yet.</div>
          ) : (
            rows.map((row) => (
              <div key={row.id} className="flex gap-3 border-b border-gray-50 px-4 py-2.5 last:border-0">
                <span className="w-[135px] shrink-0 text-[10px] text-gray-400">{row.ts ? new Date(row.ts).toLocaleString() : ""}</span>
                <div className="min-w-0">
                  <span className="text-[10px] font-bold uppercase tracking-wide text-violet-600">{row.label}</span>
                  <p className="truncate text-[11px] text-gray-700" title={row.body}>{row.body}</p>
                </div>
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );
}

import React, { useEffect, useRef } from "react";
import { Link, useLocation, useNavigate } from "react-router-dom";
import { Wrench, ArrowRight } from "lucide-react";
import { ESTIMATOR_MODULES } from "@/components/estimator/moduleRegistry";

const LINKS = [
  { label: "Quick Price", desc: "Price one module fast", to: "/QuickPrice" },
  { label: "New Estimate", desc: "Start a full all-in-one estimate", to: "/NewAllInOneEstimate" },
  { label: "Estimate Queues", desc: "Work through estimates by status", to: "/EstimatorQueues" },
  { label: "Customers", desc: "Customer records, statements and portal links", to: "/EstimatorCustomers" },
  { label: "Products", desc: "Quick-product catalog and pricing", to: "/EstimatorProducts" },
  { label: "Parts", desc: "Part catalog used by the module estimators", to: "/EstimatorParts" },
  { label: "Master Inventory", desc: "Stocked materials across modules", to: "/MasterInventory" },
  { label: "Quote Settings", desc: "Customer quote branding, terms and defaults", to: "/QuoteSettings" },
  { label: "Estimator Settings", desc: "Estimator module defaults", to: "/EstimatorSettings" },
  { label: "Data backup", desc: "Admin full estimate + parts + audit export (JSON) on Estimate Queues", to: "/EstimatorQueues" },
  { label: "Main Workflow", desc: "Jump to the shop workflow board", to: "/MainWorkflow" },
  { label: "Sales Pipeline", desc: "Leads, quotes and follow-ups", to: "/SalesPipeline" },
  { label: "Reports & Requests", desc: "Submit a bug or feature request", to: "/FeatureReports" },
];

export default function EstimatorTools() {
  const navigate = useNavigate();
  const location = useLocation();
  const moduleJumpRef = useRef("");
  // #315 — this page is a link hub (no module chooser), so ?module=<key>
  // pre-selects by forwarding to that module's estimator page.
  useEffect(() => {
    const key = new URLSearchParams(location.search).get("module") || "";
    if (!key || moduleJumpRef.current === key) return;
    const mod = ESTIMATOR_MODULES.find((m) => m.key === key);
    if (!mod) return;
    moduleJumpRef.current = key;
    navigate(`/${mod.page}?module=${encodeURIComponent(key)}`, { replace: true });
  }, [location.search, navigate]);
  return (
    <div className="clay-scope min-h-full bg-gradient-to-br from-rose-50 to-orange-50">
      <div className="max-w-3xl mx-auto p-4 sm:p-6 space-y-3">
        <div className="bg-white px-4 py-3 flex items-center gap-2">
          <Wrench className="w-4 h-4 text-red-500" />
          <h1 className="text-xs font-bold tracking-wide text-gray-600">TOOLS</h1>
        </div>

        <div className="bg-white divide-y divide-gray-100">
          {LINKS.map((l) => (
            <Link key={l.to} to={l.to} className="flex items-center justify-between px-4 py-3 hover:bg-red-50/50">
              <div>
                <div className="text-sm font-semibold text-gray-800">{l.label}</div>
                <div className="text-xs text-gray-500">{l.desc}</div>
              </div>
              <ArrowRight className="w-4 h-4 text-red-400" />
            </Link>
          ))}
        </div>
      </div>
    </div>
  );
}
